/* Grouped Gemm:: prefetch 1 arg load */
s_mov_b32 s14, 1
s_mov_b32 s59, 0
s_load_dwordx4 s[24:27], s[52:53], s58
s_cmpk_eq_u32 s20, 1                               // if gemm_count is 1?
