/* Grouped Gemm:: accumulate numTiles for each gemm */
/* Grouped Gemm:: loop start */
label_Loop_GemmCount:
s_waitcnt lgkmcnt(0)
s_lshr_b32 s56, s24, 7                             // s56 = s24 / 128
s_and_b32 s54, 127, s24                            // s54 = s24 % 128
s_addc_u32 s56, s56, 0
s_mov_b32 s55, 0                                   // STATIC_DIV: divisor=224
s_mul_i32 s54, 585, s25                            // tmp1 = dividend * magic hi
s_lshl_b64 s[54:55], s[54:55], 16                  // left shift 16 bits
s_mul_i32 s57, s25, 9363                           // tmp0 = dividend * magic lo
s_add_u32 s54, s57, s54                            // add lo
s_addc_u32 s55, s55, 0                             // add hi
s_lshr_b64 s[54:55], s[54:55], 33                  // tmp0 = quotient
