v_add_u32 v8, s11, v[vgprSerial]                   // coord 0 = wgp0 * MT0 + thread offset
s_mul_i32 s[sgprSrdBias+2], 0x2, s[sgprSrdBias+2]  // scaled by BPE
s_mul_i32 s11, s[sgprBiasStride], s[sgprWorkGroup2] // Stride * WG
